from hermes_tools import terminal, shell_quote
p='/home/USER/continual-arc-baselines/.workbench/stage1/H-hermes-luna6-medium-fresh0/frozen/seen-reference/play/users/u075/system/state/hermes/state.db'
py=r'''import sqlite3,json,collections
c=sqlite3.connect("'''+p+r'''"); sid='8c318125-bf6f-4a1e-8d15-3cc220039afd'; ms=c.execute("select id,role,content from messages where session_id=? and active=1 order by id",(sid,)).fetchall(); u=next(t for i,r,t in ms if i==1); grid=[list(map(int,l.split())) for l in u.split('Test input (27x15):\n',1)[1].split('\nWrong attempts',1)[0].splitlines() if l.strip()]; outs=[]
for i,r,t in ms:
 if r=='assistant' and t and '"action":"submit"' in t:
  try: outs.append((i,json.loads(t)['grid']))
  except:pass
D4=[(-1,0),(1,0),(0,-1),(0,1)]; D8=[(a,b) for a in (-1,0,1) for b in (-1,0,1) if a or b]
def vote(r,c,ds):
 x=collections.Counter(grid[rr][cc] for dr,dc in ds if 0<=(rr:=r+dr)<27 and 0<=(cc:=c+dc)<15); m=max(x.values()); return x,sorted(k for k,v in x.items() if v==m)
def tie_bg(w):return 3 if 3 in w else (w[0] if len(w)==1 else w)
for n,(mid,o) in enumerate(outs,1):
 if n==1:continue
 print('guess',n)
 for r in range(27):
  for c0 in range(15):
   v=o[r][c0]
   if v==grid[r][c0]: continue
   a,w4=vote(r,c0,D4); b,w8=vote(r,c0,D8); x4=tie_bg(w4); x8=tie_bg(w8)
   if v!=x4 or v!=x8:
    print((r,c0),'orig->guess',grid[r][c0],v,'4=',dict(a),w4,'choose',x4,'8=',dict(b),w8,'choose',x8)
'''
r=terminal('python3 -c '+shell_quote(py),timeout=30)
print(r['output'])

